def extract_pairwise_aucs(data):
    """Extract {pair_key: auc_value} from various JSON formats."""
    sources = []

    # Format 1: top-level "mean" dict (pairwise_auc.json)
    if "mean" in data and isinstance(data["mean"], dict):
