            p = parse_pair_key(k)
            if p and isinstance(v, (int, float)):
                pairs[k] = float(v)
        if pairs:
            sources.append(("obd_baseline", pairs))

    return sources

def check_monotonic(pairs):
    sorted_keys = sorted(pairs.keys(), key=lambda k: parse_pair_key(k))
    aucs = [(k, pairs[k]) for k in sorted_keys]
    violations = []
